Below is a step-by-step introduction to building a toy “query parser” that takes a pre-parsed SQL AST (Abstract Syntax Tree) and converts it into a relational algebra (RA) expression tree in Python. We won’t parse SQL text; instead, we’ll assume we already have Python objects that represent the SQL query AST, and we’ll translate that into an RA AST.

We’ll go incrementally:
- Step 0: Define minimal SQL and RA ASTs plus a pretty-printer to visualize results.
- Step 1: Translator for simple SELECT ... FROM single_table [WHERE ...].
- Step 2: Expand to multiple tables (implicit cross-product) in FROM (laying groundwork for joins).
- Notes: Include basic error handling and common pitfalls as we go, with examples of expected RA output.

Step 0 — Foundations: AST definitions and pretty-printing
The SQL AST captures the structure of a query (columns, literals, predicates, tables, etc.). The RA AST represents logical operators like Table (base relation), Selection (σ), Projection (π), and Product (×).

```python
from __future__ import annotations
from dataclasses import dataclass
from typing import List, Optional

# ---------- SQL AST (minimal) ----------

class SQLExpr:
    pass

@dataclass
class Column(SQLExpr):
    name: str
    table: Optional[str] = None  # qualified as table.column if given

@dataclass
class Literal(SQLExpr):
    value: object

@dataclass
class Comparison(SQLExpr):
    op: str  # e.g., '=', '<', '>'
    left: SQLExpr
    right: SQLExpr

@dataclass
class BooleanOp(SQLExpr):
    op: str  # 'AND' or 'OR'
    left: SQLExpr
    right: SQLExpr

@dataclass
class Not(SQLExpr):
    expr: SQLExpr

@dataclass
class SelectItem:
    expr: SQLExpr
    alias: Optional[str] = None

@dataclass
class AllColumns(SQLExpr):
    # Represents SELECT *
    pass

@dataclass
class TableRef:
    name: str
    alias: Optional[str] = None

@dataclass
class SelectStmt:
    select_list: List[SelectItem]         # items in SELECT clause
    from_tables: List[TableRef]           # tables in FROM clause
    where: Optional[SQLExpr] = None       # optional WHERE predicate


# ---------- Relational Algebra AST (minimal) ----------

class RAExpr:
    pass

@dataclass
class RATable(RAExpr):
    name: str
    alias: Optional[str] = None

@dataclass
class RAProduct(RAExpr):
    left: RAExpr
    right: RAExpr

@dataclass
class RASelection(RAExpr):
    predicate: SQLExpr
    child: RAExpr

@dataclass
class RAProjection(RAExpr):
    items: List[SelectItem]  # project expressions (and aliases)
    child: RAExpr


# ---------- Pretty printing helpers ----------

def expr_to_str(e: SQLExpr) -> str:
    if isinstance(e, Column):
        return f"{e.table}.{e.name}" if e.table else e.name
    if isinstance(e, Literal):
        return repr(e.value)
    if isinstance(e, Comparison):
        return f"({expr_to_str(e.left)} {e.op} {expr_to_str(e.right)})"
    if isinstance(e, BooleanOp):
        return f"({expr_to_str(e.left)} {e.op} {expr_to_str(e.right)})"
    if isinstance(e, Not):
        return f"(NOT {expr_to_str(e.expr)})"
    if isinstance(e, AllColumns):
        return "*"
    return f"<expr:{e.__class__.__name__}>"

def ra_to_str(ra: RAExpr, indent: int = 0) -> str:
    pad = "  " * indent
    if isinstance(ra, RATable):
        alias = f" AS {ra.alias}" if ra.alias else ""
        return f"{pad}Table({ra.name}{alias})"
    if isinstance(ra, RAProduct):
        return f"{pad}Product\n{ra_to_str(ra.left, indent+1)}\n{ra_to_str(ra.right, indent+1)}"
    if isinstance(ra, RASelection):
        return f"{pad}Select[{expr_to_str(ra.predicate)}]\n{ra_to_str(ra.child, indent+1)}"
    if isinstance(ra, RAProjection):
        items = ", ".join(
            f"{expr_to_str(i.expr)}" + (f" AS {i.alias}" if i.alias else "")
            for i in ra.items
        )
        return f"{pad}Project[{items}]\n{ra_to_str(ra.child, indent+1)}"
    return f"{pad}<RA:{ra.__class__.__name__}>"
```

Step 1 — Single-table SELECT-FROM-[WHERE]
Plan shape:
- RATable as the base
- Optional RASelection for WHERE
- RAProjection for the SELECT list (omit if SELECT *)

We’ll add basic validation to surface common pitfalls early: missing FROM, empty SELECT list, and enforcing “single table only” for this step.

```python
class TranslationError(Exception):
    pass

def translate_select_single_table(stmt: SelectStmt) -> RAExpr:
    # Basic validation
    if not stmt.from_tables:
        raise TranslationError("Missing FROM clause.")
    if len(stmt.from_tables) != 1:
        raise TranslationError("This step supports exactly one table in FROM.")
    if not stmt.select_list:
        raise TranslationError("Empty SELECT list is not allowed.")

    # Base relation
    base = stmt.from_tables[0]
    ra: RAExpr = RATable(name=base.name, alias=base.alias)

    # WHERE -> selection
    if stmt.where is not None:
        ra = RASelection(predicate=stmt.where, child=ra)

    # SELECT list -> projection (omit if SELECT *)
    only_star = (
        len(stmt.select_list) == 1 and isinstance(stmt.select_list[0].expr, AllColumns)
    )
    if only_star:
        return ra
    else:
        return RAProjection(items=stmt.select_list, child=ra)


# ---------- Examples (Step 1) ----------
if __name__ == "__main__":
    # Example A: SELECT id, name FROM users WHERE age > 18;
    stmt = SelectStmt(
        select_list=[SelectItem(Column("id")), SelectItem(Column("name"))],
        from_tables=[TableRef("users")],
        where=Comparison(">", Column("age"), Literal(18)),
    )
    ra = translate_select_single_table(stmt)
    print("Step 1 plan:\n" + ra_to_str(ra))

    # Example B: SELECT * FROM users;
    stmt2 = SelectStmt(
        select_list=[SelectItem(AllColumns())],
        from_tables=[TableRef("users")],
        where=None,
    )
    ra2 = translate_select_single_table(stmt2)
    print("\nStep 1 plan (SELECT *):\n" + ra_to_str(ra2))

    # Example C (pitfall): missing FROM
    try:
        bad = SelectStmt(select_list=[SelectItem(Column("id"))], from_tables=[], where=None)
        translate_select_single_table(bad)
    except TranslationError as e:
        print("\nExpected error (missing FROM):", e)
```

Expected output (formatted tree):
- Example A: a Project node over a Select node over Table(users)
- Example B: just Table(users) (no projection node for SELECT *)
- Example C: raises TranslationError("Missing FROM clause.")

Step 2 — Multiple tables in FROM (implicit cross-product)
Many real queries list multiple tables (e.g., FROM A, B). Relationally, this is a cross-product of all tables, followed by WHERE (which can include join predicates), then projection. This step sets the stage for explicit JOIN support later.

Algorithm:
- Fold tables into a left-deep RAProduct chain: (((T1 × T2) × T3) × ...)
- Apply WHERE as RASelection above the product
- Apply RAProjection (unless SELECT *)

```python
def fold_product(tables: List[TableRef]) -> RAExpr:
    assert len(tables) >= 1
    ra: RAExpr = RATable(tables[0].name, alias=tables[0].alias)
    for tr in tables[1:]:
        ra = RAProduct(left=ra, right=RATable(tr.name, alias=tr.alias))
    return ra

def translate_select_multi_table(stmt: SelectStmt) -> RAExpr:
    # Validation
    if not stmt.from_tables:
        raise TranslationError("Missing FROM clause.")
    if not stmt.select_list:
        raise TranslationError("Empty SELECT list is not allowed.")

    # Build product of all tables
    ra: RAExpr = fold_product(stmt.from_tables)

    # WHERE -> selection
    if stmt.where is not None:
        ra = RASelection(predicate=stmt.where, child=ra)

    # SELECT list -> projection (omit if SELECT *)
    only_star = (
        len(stmt.select_list) == 1 and isinstance(stmt.select_list[0].expr, AllColumns)
    )
    if only_star:
        return ra
    else:
        return RAProjection(items=stmt.select_list, child=ra)


# ---------- Example (Step 2) ----------
if __name__ == "__main__":
    # SELECT u.id, o.total
    # FROM users AS u, orders AS o
    # WHERE u.id = o.user_id AND o.total > 100;
    stmt3 = SelectStmt(
        select_list=[SelectItem(Column("id", table="u")),
                     SelectItem(Column("total", table="o"))],
        from_tables=[TableRef("users", alias="u"), TableRef("orders", alias="o")],
        where=BooleanOp(
            "AND",
            left=Comparison("=", Column("id", "u"), Column("user_id", "o")),
            right=Comparison(">", Column("total", "o"), Literal(100)),
        ),
    )
    ra3 = translate_select_multi_table(stmt3)
    print("\nStep 2 plan (multi-table):\n" + ra_to_str(ra3))
```

What you should see for Step 2:
- A left-deep Product tree of users AS u and orders AS o.
- A Selection node with the conjunction of the join predicate (u.id = o.user_id) and the filter (o.total > 100).
- A Projection node for the selected columns.

Common pitfalls and how this tutorial addresses them
- Missing FROM or empty SELECT list: surfaced as TranslationError with clear messages.
- Confusing SELECT * handling: we omit the RAProjection node when the list is exactly [*].
- Multiple tables without predicates: the RA tree correctly shows a cross-product; real systems often rely on WHERE or JOIN ... ON to constrain this.
- Next steps (recommended): add explicit JOIN nodes or translate JOIN ... ON to product + selection; add name resolution and a simple catalog to catch unknown/ambiguous columns; extend to GROUP BY/aggregates.

This provides a clear, incremental path: start with a minimal single-table translator, then support multiple tables via products and selections, all while producing readable RA ASTs you can inspect.
